(function () {
    'use strict';
    const R = window.RackStudio, escape = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
    const meter = n => n === null || n === undefined ? 'Bilinmiyor' : n + ' m';
    const css = 'body{font:12px Arial,sans-serif;color:#172b35;margin:24px;background:white;overflow-wrap:anywhere}h1{font-size:24px}h2{font-size:18px;margin-top:24px}p{line-height:1.5}table{border-collapse:collapse;width:100%;table-layout:fixed;margin:12px 0}th,td{border:1px solid #cbd5dc;padding:7px;text-align:left;overflow-wrap:anywhere;vertical-align:top}th{background:#edf2f4}thead{display:table-header-group}tr{break-inside:avoid}svg{max-width:100%;height:auto}.rack{break-inside:avoid;max-width:520px}small{color:#52616b}@page{size:A4;margin:14mm}@media print{body{margin:0}button{display:none}h2{break-after:avoid}}';
    function table(headers, rows) { return '<table><thead><tr>' + headers.map(h => '<th>' + escape(h) + '</th>').join('') + '</tr></thead><tbody>' + rows.map(row => '<tr>' + row.map(v => '<td>' + escape(v) + '</td>').join('') + '</tr>').join('') + '</tbody></table>'; }
    function rackSVG(model, rack, selectedFace) {
        const h=rack.heightU*12+44, faces=selectedFace?[selectedFace]:['front', ...(model.devices.some(d=>d.rackId===rack.id&&d.face==='rear')?['rear']:[])];
        const panels=faces.map((face,index)=>{
            const devices=model.devices.filter(d=>d.rackId===rack.id&&d.face===face),label=face==='rear'?'Arka yüz':'Ön yüz';
            return '<g transform="translate('+index*480+',0)"><text x="42" y="16" font-family="Roboto" font-size="11">'+escape(rack.name+' · '+label)+'</text><rect x="42" y="28" width="425" height="'+rack.heightU*12+'" fill="#f5f7f8" stroke="#41616b"/>'+Array.from({length:rack.heightU},(_,i)=>'<text x="4" y="'+(40+i*12)+'" font-family="Roboto" font-size="9">U'+(rack.heightU-i)+'</text>').join('')+devices.map(d=>{
                const y=28+(rack.heightU-d.topU)*12,height=d.uHeight*12;
                return '<g data-id="'+escape(d.id)+'" data-face="'+face+'"><title>'+escape(d.name+' · '+d.id)+'</title><rect x="48" y="'+y+'" width="412" height="'+height+'" fill="#dae7eb" stroke="#41616b"/><text x="54" y="'+(y+9)+'" font-family="Roboto" font-size="9">'+escape(R.LabelModel.short(d.name+' · '+d.model,66))+'</text></g>';
            }).join('')+'</g>';
        }).join('');
        const w=480*faces.length;
        return '<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'"><title>'+escape(rack.name)+'</title>'+panels+'</svg>';
    }
    function reportHTML(model, options = {}) { const doc = model.document, bom = R.BOM.build(model, options.bom), inventory = model.devices.map(d => [d.id, d.rack, 'U' + d.topU + ' · ' + d.face, d.name, d.model, d.serialNumber || 'Belirtilmedi', d.ipAddress || 'Belirtilmedi']), cables = model.cables.map(c => [c.id, c.name, c.from.label, c.to.label, c.medium || 'Belirtilmedi', c.role || 'Belirtilmedi', meter(c.estimated), meter(c.measured), meter(c.purchase)]); return '<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; img-src data:"><title>' + escape(doc.metadata.name || 'Proje raporu') + '</title><style>' + css + '</style></head><body><h1>' + escape(options.company || doc.metadata.customer || 'Rack Studio') + '</h1><h2>' + escape(doc.metadata.name || 'Adsız proje') + '</h2><p>Proje ' + escape(doc.projectId) + ' · revizyon ' + doc.revision + ' · ' + escape(model.source.name) + '<br>Hazırlayan: ' + escape(doc.metadata.owner || 'Belirtilmedi') + ' · ' + escape(model.createdAt) + '<br>Teknik durum: ' + (model.technicalComplete ? 'Tamamlandı' : 'Açık işler var') + ' · Teslim kabulü ayrı kayıttır.</p><h2>Kabin görünümü</h2>' + doc.topology.racks.map(r => '<section class="rack"><h3>' + escape(r.name) + ' · ' + r.heightU + 'U</h3>' + rackSVG(model, r) + '</section>').join('') + '<h2>Envanter</h2>' + table(['Kimlik', 'Kabin', 'Konum', 'Cihaz', 'Model', 'Seri', 'IP'], inventory) + '<h2>Bağlantılar</h2>' + table(['Kimlik', 'Etiket', 'Kaynak', 'Hedef', 'Ortam', 'Rol', 'Tahmin', 'Ölçüm', 'Satın alma'], cables) + '<h2>Gözlemler</h2>' + table(['Kimlik', 'Nesne', 'Kaynak', 'Zaman', 'Not'], doc.observations.map(o => [o.id, o.entityRef?.id || 'Eşleşmedi', typeof o.source === 'string' ? o.source : o.source?.filename || o.source?.system || 'Belirtilmedi', o.collectedAt || o.receivedAt || 'Belirtilmedi', o.note || JSON.stringify(o.normalized || o.raw || {})])) + '<h2>Açık işler</h2>' + table(['Tür', 'Kimlik', 'İş'], model.issues.map(i => [i.kind, i.id, i.text])) + '<h2>Malzeme listesi</h2>' + table(['Kalem', 'Tür', 'Miktar', 'Birim fiyat', 'Ara toplam', 'Kaynak kimlikler'], bom.rows.map(r => [r.name, r.kind, r.quantity, r.unitPrice ?? 'Girilmedi', r.totalPrice ?? 'Hesaplanmadı', r.sourceIds.join(', ')])) + '<p>Fiyatlı kalemler ara toplamı: ' + bom.totalPrice + ' ' + escape(bom.options.currency) + ' · ' + bom.unpricedRows + ' kalemde fiyat eksik.</p>' + table(['Metraj', 'Bilinen toplam', 'Bilinen hat', 'Bilinmeyen hat'], Object.entries(bom.totals).map(([k, v]) => [k, meter(v.meters), v.known, v.unknown])) + table(['Bilinmeyen kalem', 'Kaynak', 'Gerekçe'], bom.unknown.map(r => [r.name, r.sourceIds.join(', '), r.reason])) + '<p>' + bom.notes.map(escape).join('<br>') + '</p></body></html>'; }
    const cell = value => { let v = String(value ?? ''); if (/^[=+\-@\t\r]/.test(v))
        v = "'" + v; return '"' + v.replace(/"/g, '""') + '"'; };
    function csv(headers, rows) { return '\ufeff' + [headers, ...rows].map(row => row.map(cell).join(',')).join('\r\n') + '\r\n'; }
    function cablesCSV(model) { return csv(['projectId', 'revision', 'cableId', 'name', 'fromRackId', 'fromDeviceId', 'fromPortId', 'fromFace', 'fromLabel', 'toRackId', 'toDeviceId', 'toPortId', 'toFace', 'toLabel', 'medium', 'role', 'estimatedMeters', 'measuredMeters', 'purchaseMeters', 'legacyMeters', 'note'], model.cables.map(c => [model.document.projectId, model.document.revision, c.id, c.name, c.from.rackId, c.from.deviceId, c.from.portId, c.from.face, c.from.label, c.to.rackId, c.to.deviceId, c.to.portId, c.to.face, c.to.label, c.medium, c.role, c.estimated, c.measured, c.purchase, c.legacy, c.note])); }
    function bomCSV(model, options) { const b = R.BOM.build(model, options); return csv(['projectId', 'revision', 'key', 'name', 'quantity', 'stockLengthMeters', 'unitPrice', 'subtotal', 'currency', 'sourceIds'], b.rows.map(r => [model.document.projectId, model.document.revision, r.key, r.name, r.quantity, r.stockLength, r.unitPrice, r.totalPrice, b.options.currency, r.sourceIds.join('|')])); }
    function download(data, name, mime = 'text/plain') { const url = URL.createObjectURL(data instanceof Blob ? data : new Blob([data], { type: mime })), a = document.createElement('a'); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 10000); }
    R.ReportOutput = Object.freeze({ escape, table, css, meter, rackSVG, html: reportHTML, csv, cablesCSV, bomCSV, download });
})();
